let providerRequestTail=Promise.resolve();

async function api(path,data){if(path.startsWith('market-')||path.startsWith('intelligence-'))return rawApi(path,data);if(['sync','refresh-prices','history','wallet-details','discover-tokens','market-listings','market-detail','market-chart','market-fundamentals','market-news','intelligence-overview','intelligence-narrative','intelligence-rsi','intelligence-venues','intelligence-flow','intelligence-derivatives','intelligence-exposures','market-watch-toggle','market-watchlist'].includes(path)){const pending=providerRequestTail.then(()=>rawApi(path,data));providerRequestTail=pending.catch(()=>{});return pending}return rawApi(path,data)}

async function rawApi(path,data){const r=await fetch('/api/'+path,{method:data?'POST':'GET',headers:{'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});const j=await r.json();if(!r.ok){const e=Error(j.error||'Request failed');e.status=r.status;throw e;}return j}

async function load(){try{state=await api('state');$('auth').classList.add('hidden');$('email').textContent=state.profile?.name||state.email;render();if(!initialWalletSync&&state.wallets.some(w=>!w.snapshot)){initialWalletSync=true;await refresh($('syncWallets'),'sync')}queueMissingHistory()}catch(e){if(e.status===401)$('auth').classList.remove('hidden');else toast('Could not load portfolio: '+e.message)}}

function pnl(n){return '<span class="'+(n>=0?'positive':'negative')+'">'+money(n)+'</span>'}

function render(){loadDashboardPreferences();const a=state.assets;const sum=k=>a.reduce((n,x)=>n+(x[k]||0),0);const complete=a.filter(x=>x.quantity>0).every(x=>x.price!==null);$('value').textContent=a.length&&complete?money(sum('value')):'—';$('cost').textContent=money(sum('cost'));$('realized').innerHTML=pnl(sum('realized'));$('unrealized').innerHTML=a.length&&complete?pnl(sum('unrealized')):'—';$('assetCount').textContent=a.length+' assets';$('assetEmpty').classList.toggle('hidden',a.length>0);$('assets').innerHTML=a.map(x=>`<tr><td><span class="token">${esc(x.symbol.slice(0,3))}</span><b>${esc(x.symbol)}</b></td><td>${num(x.quantity)}</td><td>${money(x.average_buy)}</td><td>${x.sold?money(x.average_sell):'—'}</td><td><button data-price="${esc(x.symbol)}">${x.price===null?'+ Set price':money(x.price)}</button><div class="small muted">${quoteLabel(x.symbol)}</div></td><td>${money(x.value)}</td><td>${x.unrealized===null?'—':pnl(x.unrealized)}</td><td>${pnl(x.realized)}</td></tr>`).join('');renderTrades();renderWallets();renderHistory();renderReviews();renderNetworkSupport();renderInsights();restoreTokenControls();renderAdvanced();renderTargets()}   

function renderTrades(){const q=$('search').value.toLowerCase(),side=$('sideFilter').value,from=$('dateFrom').value,to=$('dateTo').value;const rows=state.trades.filter(t=>(t.symbol+' '+t.account).toLowerCase().includes(q)&&(!side||t.side===side)&&(!from||t.date.slice(0,10)>=from)&&(!to||t.date.slice(0,10)<=to)).slice().reverse();$('tradeSummary').textContent=rows.length+' of '+state.trades.length+' trades · Gross buys '+money(rows.filter(t=>t.side==='buy').reduce((n,t)=>n+t.quantity*t.price,0))+' · Gross sells '+money(rows.filter(t=>t.side==='sell').reduce((n,t)=>n+t.quantity*t.price,0))+' · Fees '+money(rows.reduce((n,t)=>n+Number(t.fee),0));$('tradeEmpty').textContent=state.trades.length?'No trades match these filters.':'No trades yet. Add a purchase or import your history.';$('tradeEmpty').classList.toggle('hidden',rows.length>0);$('trades').innerHTML=rows.map(t=>`<tr><td>${esc(t.date.replace('T',' '))}</td><td><b>${esc(t.symbol)}</b></td><td class="${t.side==='buy'?'positive':'muted'}">${esc(t.side.toUpperCase())}</td><td>${num(t.quantity)}</td><td>${money(+t.price)}</td><td>${money(t.quantity*t.price)}</td><td>${money(+t.fee)}</td><td>${esc(t.account)}</td><td><button data-delete="${t.id}" aria-label="Delete ${esc(t.symbol)} ${esc(t.side)} trade from ${esc(t.date)}">×</button></td></tr>`).join('')}

