function renderWalletDetails(result){const tokens=result.tokens||{},activity=result.activity||{},rows=tokens.tokens||[],items=activity.items||[];const errors=[...(tokens.errors||[]),...(activity.errors||[])];$('detailsResults').innerHTML='<h2>Token balances</h2><p class="small">'+esc(tokens.coverage||'Provider coverage unavailable')+'</p>'+errors.map(e=>'<p class="negative">'+esc(typeof e==='string'?e:JSON.stringify(e))+'</p>').join('')+(rows.length?'<div class="table-wrap"><table><thead><tr><th>Contract / mint identity</th><th>Quantity</th><th>Token price</th><th>USD value</th><th>Identity</th></tr></thead><tbody>'+rows.map(t=>'<tr><td style="white-space:normal;overflow-wrap:anywhere;max-width:380px">'+esc(t.symbol||'Unknown token')+' '+esc(t.name||'')+'<div class="small muted">'+esc(t.contract||t.mint||t.asset_id||'Unknown identity')+'</div></td><td>'+esc(t.quantity)+(t.stale?'<div class="negative small">Stale · last known balance</div>':'')+'</td>'+tokenPriceCells(t)+'<td>Unverified</td></tr>').join('')+'</tbody></table></div>':'<p>No token balances returned. Provider coverage may be limited.</p>')+'<h2 style="margin-top:24px">Recent activity</h2><p class="small">Most recent 25 transactions; this is not complete history. Activity is not classified as buys or sells.</p><p class="small">'+esc(activity.coverage||'Activity history is unavailable for this chain.')+'</p>'+(items.length?'<div class="table-wrap"><table><thead><tr><th>Date</th><th>Transaction identity</th><th>Status</th></tr></thead><tbody>'+items.map(t=>'<tr><td>'+esc(t.date||t.timestamp||'—')+'</td><td style="white-space:normal;overflow-wrap:anywhere;max-width:380px">'+esc(t.hash||t.signature||t.digest||t.id||'—')+'</td><td>'+esc(t.status||'—')+'</td></tr>').join('')+'</tbody></table></div>':'<p>No recent activity returned. Transfers here are not classified as purchases or sales.</p>')}

