const historyRequested=new Set(),historyPending=new Set(),tokenRequested=new Set(),tokenPending=new Set();

async function queueMissingHistory(){if(historyQueueRunning||historyPause)return;historyQueueRunning=true;const candidates=(state.wallets||[]).filter(w=>!(state.history_status||[]).some(h=>Number(h.wallet_id)===Number(w.id)&&h.adapter_version===2)&&!historyRequested.has(state.email+':'+w.id));try{for(const wallet of (state.wallets||[]).filter(w=>(!w.token_snapshot||w.token_snapshot.price_version!==1)&&!tokenRequested.has(state.email+':'+w.id))){if(historyPause)break;const key=state.email+':'+wallet.id;tokenRequested.add(key);try{await discoverTokens(wallet.id,true)}catch(e){if(e.status===429)tokenRequested.delete(key)}}for(const wallet of candidates){if(historyPause)break;const key=state.email+':'+wallet.id;historyRequested.add(key);historyPending.add(Number(wallet.id));renderHistory();try{await api('history',{id:Number(wallet.id),more:false});await load()}catch(e){if(e.status===429)historyRequested.delete(key);toast('History sync: '+e.message)}finally{historyPending.delete(Number(wallet.id));renderHistory()}}}finally{historyQueueRunning=false}}

async function fetchHistory(id,more){if(historyPending.has(Number(id)))return;historyPending.add(Number(id));renderHistory();try{await api('history',{id:Number(id),more:!!more});await load()}catch(e){toast('History sync: '+e.message)}finally{historyPending.delete(Number(id));renderHistory()}}

function historyHash(chain,hash){const bases={Bitcoin:'https://mempool.space/tx/',Stellar:'https://stellar.expert/explorer/public/tx/',Tron:'https://tronscan.org/#/transaction/',Arc:'https://explorer.arc.io/tx/',Monad:'https://monadscan.com/tx/','Robinhood Chain':'https://robinhoodchain.blockscout.com/tx/',Linea:'https://lineascan.build/tx/',Sonic:'https://sonicscan.org/tx/',Gnosis:'https://gnosisscan.io/tx/',Celo:'https://celoscan.io/tx/',Base:'https://basescan.org/tx/',Arbitrum:'https://arbiscan.io/tx/',Polygon:'https://polygonscan.com/tx/',Avalanche:'https://snowtrace.io/tx/',Ethereum:'https://etherscan.io/tx/',Optimism:'https://optimistic.etherscan.io/tx/','BNB Chain':'https://bscscan.com/tx/',Solana:'https://solscan.io/tx/',Aptos:'https://explorer.aptoslabs.com/txn/',Sui:'https://suiscan.xyz/mainnet/tx/'};const valid=['Bitcoin','Stellar','Tron'].includes(chain)?/^[0-9a-fA-F]{64}$/.test(hash):['Solana','Sui'].includes(chain)?/^[1-9A-HJ-NP-Za-km-z]{32,88}$/.test(hash):/^0x[0-9a-fA-F]{64}$/.test(hash);return bases[chain]&&valid?'<a href="'+bases[chain]+hash+'" target="_blank" rel="noopener noreferrer">'+esc(hash.slice(0,12))+'…</a>':esc(hash||'—')}

function renderHistory(){const history=state.history||[],statuses=state.history_status||[];$('historyWallets').innerHTML=(state.wallets||[]).map(w=>{const status=statuses.find(h=>Number(h.wallet_id)===Number(w.id)),busy=historyPending.has(Number(w.id));return '<div class="connection" style="margin-bottom:12px"><div class="row"><b>'+esc(w.label)+' · '+esc(w.chain)+'</b><div class="actions"><button data-history="'+w.id+'" '+(busy?'disabled':'')+'>'+(busy?'Fetching history…':'Refresh history')+'</button>'+(status?.has_more?'<button data-history-more="'+w.id+'" '+(busy?'disabled':'')+'>Load older activity</button>':'')+'</div></div><p class="small">'+esc(status?.coverage||'History not synced yet.')+'</p>'+(status?.error?'<p class="negative">'+esc(status.error)+'</p>':'')+(status?.updated_at?'<span class="small muted">Last fetched '+new Date(status.updated_at*1000).toLocaleString()+'</span>':'')+'</div>'}).join('');$('historyEmpty').classList.toggle('hidden',history.length>0);$('historyEmpty').textContent=(state.wallets||[]).length?'No on-chain events loaded. Check each wallet’s coverage and sync status above.':'Add a wallet to load its on-chain activity.';$('chainHistory').innerHTML=history.map(t=>'<tr><td>'+esc(t.date||'—')+'</td><td>'+esc(t.wallet_label||'Wallet')+'<div class="small muted">'+esc(t.chain)+'</div></td><td>'+esc(t.kind||'Activity')+'<div class="small muted">'+esc(t.direction||'—')+'</div></td><td style="white-space:normal;overflow-wrap:anywhere;max-width:220px">'+esc(t.asset||'Unknown')+(t.asset_id?'<div class="small muted">'+esc(t.asset_id)+'</div>':'')+'</td><td>'+esc(t.quantity??(t.raw_quantity!==undefined?t.raw_quantity+' raw units (decimals unknown)':'—'))+'</td><td>'+esc(t.fee??'—')+'</td><td>'+esc(t.status||'—')+'</td><td>'+historyHash(t.chain,t.hash)+'</td></tr>').join('')}

$('historyWallets').onclick=e=>{const b=e.target.closest('[data-history],[data-history-more]');if(b)fetchHistory(Number(b.dataset.history||b.dataset.historyMore),!!b.dataset.historyMore)};



let selectedReview=null;

function reviewLegs(items){return (items||[]).map(t=>'<div><b>'+esc(t.quantity)+' '+esc(t.asset)+'</b><div class="small muted" style="overflow-wrap:anywhere">'+esc(t.asset_id)+'</div></div>').join('')||'<span class="muted">None detected</span>'}

function renderReviews(){const reviews=state.reviews||[];$('reviewItems').innerHTML=reviews.length?reviews.map(r=>'<div class="panel"><div class="panel-head"><h2>'+esc(({swap_candidate:'Suggested swap',acquisition_review:'Incoming asset · purchase review',complex_activity:'Complex activity',disposal_review:'Outgoing asset review'})[r.kind]||'Activity review')+'</h2><span class="pill">'+esc(r.status)+'</span></div><p>'+esc(r.wallet_label)+' · '+esc(r.chain)+' · '+esc(r.date)+'</p><div class="fields"><div><p>Sent</p>'+reviewLegs(r.sent)+'</div><div><p>Received</p>'+reviewLegs(r.received)+'</div></div><p class="small" style="overflow-wrap:anywhere">Transaction: '+esc(r.hash)+'<br>Native fee: '+esc(r.native_fee??'Unavailable')+'</p>'+(r.warnings||[]).map(w=>'<p class="negative">'+esc(w)+'</p>').join('')+(r.kind==='acquisition_review'?'<p class="small">An incoming transfer is not proof of purchase. Only record the original acquisition if you can verify its actual date and cost.</p>':'')+(r.status==='pending'?'<div class="actions">'+(['swap_candidate','acquisition_review'].includes(r.kind)?'<button class="primary" data-review-open="'+esc(r.id)+'">'+(r.kind==='acquisition_review'?'Record original purchase':'Review suggested swap')+'</button>':'')+'<button data-review-dismiss="'+esc(r.id)+'">Dismiss / transfer handled</button></div>':'')+'</div>').join(''):'<div class="panel empty"><b>No activity needs review</b>Sync wallet history to inspect supported activity. Recorded trades are added only with your explicit confirmation.</div>'}

function ledgerAlias(t){if(!t)return '';if(t.ledger_symbol)return t.ledger_symbol;return /(^|[:/])native$/i.test(t.asset_id||'')||t.asset_id==='ETH'?({'Ethereum':'ETH','Optimism':'ETH_OP','Bitcoin':'BTC','Stellar':'XLM','Tron':'TRX','Arc':'USDC_ARC','Monad':'MON','Robinhood Chain':'ETH_RH','Linea':'ETH_LINEA','Sonic':'S','Gnosis':'XDAI','Celo':'CELO','Base':'ETH_BASE','Arbitrum':'ETH_ARB','Polygon':'POL','Avalanche':'AVAX','BNB Chain':'BNB','Solana':'SOL','Aptos':'APT','Sui':'SUI'}[String(t.asset_id).split(':')[0]]||String(t.asset||'ETH')):'TOKEN_'+String(t.asset_id||'UNKNOWN').replace(/[^a-zA-Z0-9]/g,'').slice(-8).toUpperCase()}

$('reviewItems').onclick=async e=>{const open=e.target.closest('[data-review-open]'),dismiss=e.target.closest('[data-review-dismiss]');if(open){selectedReview=(state.reviews||[]).find(r=>r.id===open.dataset.reviewOpen);if(!selectedReview)return;const acquisition=selectedReview.kind==='acquisition_review';$('reviewDialogTitle').textContent=acquisition?'Record original purchase':'Review suggested swap';$('reviewContext').textContent=selectedReview.chain+' · '+selectedReview.hash+' · Received identities: '+(selectedReview.received||[]).map(t=>t.asset_id).join(', ')+' · Sent identities: '+(selectedReview.sent||[]).map(t=>t.asset_id).join(', ');$('reviewDate').value=String(selectedReview.date||'').slice(0,19);$('reviewValueLabel').firstChild.textContent=acquisition?'Actual total purchase cost (USD)':'Total exchanged value (USD)';$('reviewValue').value='';$('reviewFee').value='0';$('sentAliasLabel').classList.toggle('hidden',acquisition);$('sentAlias').required=!acquisition;$('sentAlias').value=ledgerAlias(selectedReview.sent?.[0]);$('receivedAlias').value=ledgerAlias(selectedReview.received?.[0]);$('reviewAcknowledge').checked=false;$('reviewError').textContent='';$('confirmReview').textContent=acquisition?'Record original purchase':'Confirm and record swap';$('reviewDialog').showModal()}else if(dismiss){dismiss.disabled=true;try{await api('review',{id:dismiss.dataset.reviewDismiss,action:'dismiss'});await load();toast('Activity dismissed. No trades were recorded.')}catch(e){toast(e.message);dismiss.disabled=false}}};

$('reviewForm').onsubmit=async e=>{e.preventDefault();if(!selectedReview||!$('reviewAcknowledge').checked)return;const button=$('confirmReview');if(button.disabled)return;button.disabled=true;$('reviewError').textContent='';try{await api('review',{id:selectedReview.id,action:'confirm',date:$('reviewDate').value,usd_value:$('reviewValue').value,fee_usd:$('reviewFee').value,sent_symbol:$('sentAlias').value,received_symbol:$('receivedAlias').value,acknowledge:true});$('reviewDialog').close();await load();toast('Verified trades recorded. Portfolio P&L updated.')}catch(e){$('reviewError').textContent=e.message}finally{button.disabled=false}};



async function discoverTokens(id,automatic=false){id=Number(id);if(tokenPending.has(id))return;tokenPending.add(id);renderWallets();try{await api('discover-tokens',{id});await load();if(!automatic)toast('Token checks updated. Review partial coverage and any provider errors.')}catch(e){toast('Token discovery: '+e.message);throw e}finally{tokenPending.delete(id);renderWallets()}}

function tokenError(error){return typeof error==='string'?error:JSON.stringify(error)}

function walletTokenList(wallet){const snapshot=wallet.token_snapshot;if(!snapshot)return '<div class="notice small">Token discovery has not completed. Refresh tokens checks supported catalog, saved contracts, and configured providers; it does not guarantee every token.</div>';const tokens=snapshot.tokens||[],nonzero=tokens.filter(t=>t.quantity!==null&&t.quantity!==undefined&&!/^0(?:\.0+)?$/.test(String(t.quantity))),zeros=tokens.filter(t=>t.quantity!==null&&t.quantity!==undefined&&/^0(?:\.0+)?$/.test(String(t.quantity)));return '<div class="notice small"><b>Token coverage · partial</b><div>'+esc(snapshot.coverage||'Only supported token sources and saved contracts are checked.')+'</div>'+(snapshot.has_more?'<div>More provider results exist; this snapshot is incomplete.</div>':'')+(snapshot.updated_at?'<div>Checked '+new Date(snapshot.updated_at*1000).toLocaleString()+'</div>':'')+'</div>'+(snapshot.error?'<p class="negative">'+esc(snapshot.error)+'</p>':'')+(snapshot.errors||[]).map(e=>'<p class="negative small">'+esc(tokenError(e))+'</p>').join('')+(nonzero.length?'<div class="table-wrap"><table><thead><tr><th>Token / identity</th><th>Exact balance</th><th>Token price</th><th>USD value</th></tr></thead><tbody>'+nonzero.map(t=>'<tr><td><b>'+esc(t.symbol||'Unknown token')+'</b> '+esc(t.name||'')+'<div class="small muted" style="white-space:normal;overflow-wrap:anywhere;max-width:390px">'+esc(t.contract||t.mint||t.asset_id||'Unknown identity')+' · Unverified metadata</div></td><td>'+esc(t.quantity)+(t.stale?'<div class="negative small">Stale · last known balance</div>':'')+'</td>'+tokenPriceCells(t)+'</tr>').join('')+'</tbody></table></div>':'<p class="small muted">No nonzero token balances returned from the sources checked. This does not establish that the wallet contains no other tokens.</p>')+(zeros.length?'<details class="small"><summary>'+zeros.length+' queried contracts returned zero balance</summary>'+zeros.map(t=>'<p style="overflow-wrap:anywhere">'+esc(t.symbol||'Token')+' · '+esc(t.contract||t.mint||t.asset_id)+' · '+esc(t.quantity)+(t.stale?' · Stale · last known balance':'')+'</p>').join('')+'</details>':'')}

function chainBadge(chain){return '<span class="chain-badge">'+esc(chain)+'</span>'}
function overviewTokenHoldings(wallets){
 const rows=wallets.flatMap(w=>(w.token_snapshot?.tokens||[]).filter(t=>t.quantity!==null&&t.quantity!==undefined&&!/^0(?:\.0+)?$/.test(String(t.quantity))).map(t=>({wallet:w,token:t})));
 const chains=[...new Set(wallets.map(w=>w.chain))];
 return '<div class="holdings-heading"><div><span class="eyebrow">ASSETS ACROSS YOUR NETWORKS</span><h2>Token holdings <span class="count-badge">'+rows.length+'</span></h2></div><span class="pill">USD valuations</span></div><div class="holdings-filters"><label>Find a token<input id="tokenSearch" placeholder="Search token, contract or wallet" type="search"></label><label>Network<select id="tokenChain"><option value="">All networks</option>'+chains.map(c=>'<option>'+esc(c)+'</option>').join('')+'</select></label><label>Sort by<select id="tokenSort"><option value="value">Highest value</option><option value="name">Token A–Z</option><option value="low">Lowest value</option></select></label><label>Quote status<select id="tokenQuote"><option value="all">All quotes</option><option value="priced">Priced</option><option value="unpriced">Unpriced</option><option value="stale">Stale quotes</option></select></label><label class="dust-toggle"><input type="checkbox" id="tokenDust"> Hide below $1</label></div><p id="tokenFilterSummary" class="small muted" role="status"></p>'+(rows.length?'<div class="table-wrap"><table class="holdings-table"><thead><tr><th>Token / network</th><th>Balance</th><th>Market price</th><th>Holding value</th><th>Purchase cost</th></tr></thead><tbody>'+rows.map(({wallet:w,token:t})=>'<tr data-token-row data-stale="'+(tokenQuoteStale(t)?'yes':'no')+'" data-value="'+(knownQuote(t.value_usd)?Number(t.value_usd):'')+'" data-name="'+esc((t.symbol||'Unknown').toLowerCase())+'" data-chain="'+esc(w.chain)+'" data-search="'+esc([t.symbol,t.name,t.contract,t.mint,w.label,w.chain].join(' ').toLowerCase())+'"><td><div class="asset-identity"><span class="token">'+esc((t.symbol||'?').slice(0,3))+'</span><div><b>'+esc(t.symbol||'Unknown token')+'</b><span class="asset-name">'+esc(t.name||'')+'</span></div></div><div class="identity-meta">'+chainBadge(w.chain)+'<span>'+esc(w.label)+'</span></div><details class="contract-details"><summary>Contract &amp; identity</summary><code>'+esc(t.contract||t.mint||t.asset_id)+'</code><span>Unverified token metadata</span></details></td><td class="balance-cell"><b title="'+esc(t.quantity)+'">'+esc(num(Number(t.quantity)))+'</b><details class="contract-details"><summary>Exact balance</summary><code>'+esc(t.quantity)+'</code></details>'+(t.stale?'<span class="status-warning">Stale balance</span>':'')+'</td>'+tokenPriceCells(t)+'<td><span class="cost-missing">Cost not linked</span><div class="small muted">Add original purchases<br>to calculate P&amp;L</div></td></tr>').join('')+'</tbody></table></div><p id="tokenFilterEmpty" class="empty hidden">No tokens match your search.</p>':'<div class="empty">No token holdings returned yet. Check token coverage in Connections.</div>')+'<div class="holdings-footnote"><span class="status-dot"></span>Partial token coverage · Values are market estimates.<details><summary>About cost &amp; coverage</summary><p>Quotes match network and contract. Some tokens may be missing or unpriced. Wallet balances do not establish purchase cost; record original buys and sells in the trade ledger below. Token costs are not automatically matched to ledger aliases.</p></details></div>';
}
function restoreTokenControls(){if(!$('tokenSearch'))return;const focused=document.activeElement?.id;for(const [id,key] of [['tokenSearch','search'],['tokenChain','chain'],['tokenSort','sort'],['tokenQuote','quote']])$(id).value=tokenControls[key];$('tokenDust').checked=tokenControls.dust;$('tokenSort').onchange=applyTokenFilters;$('tokenQuote').onchange=applyTokenFilters;$('tokenDust').onchange=applyTokenFilters;applyTokenFilters();if(['tokenSearch','tokenChain','tokenSort'].includes(focused))$(focused)?.focus()}
function applyTokenFilters(){if(!$('tokenSearch'))return;tokenControls={search:$('tokenSearch').value,chain:$('tokenChain').value,sort:$('tokenSort').value,dust:$('tokenDust').checked,quote:$('tokenQuote').value};saveDashboardPreferences();const q=tokenControls.search.toLowerCase(),chain=tokenControls.chain;let visible=0,hiddenDust=0,dustValue=0;const rows=[...document.querySelectorAll('[data-token-row]')];rows.sort((a,b)=>{if(tokenControls.sort==='name')return a.dataset.name.localeCompare(b.dataset.name);const av=a.dataset.value,bv=b.dataset.value;return av===''?(bv===''?a.dataset.name.localeCompare(b.dataset.name):1):bv===''?-1:tokenControls.sort==='low'?Number(av)-Number(bv):Number(bv)-Number(av)});for(const row of rows){row.parentNode.appendChild(row);const match=(!chain||row.dataset.chain===chain)&&row.dataset.search.includes(q)&&(tokenControls.quote==='all'||tokenControls.quote==='priced'&&row.dataset.value!==''||tokenControls.quote==='unpriced'&&row.dataset.value===''||tokenControls.quote==='stale'&&row.dataset.value!==''&&row.dataset.stale==='yes'),dust=tokenControls.dust&&row.dataset.value!==''&&Number(row.dataset.value)<1;if(match&&dust){hiddenDust++;dustValue+=Number(row.dataset.value)}row.hidden=!match||dust;if(!row.hidden)visible++}$('tokenFilterEmpty')?.classList.toggle('hidden',visible>0);$('tokenFilterSummary').textContent=visible+' of '+rows.length+' holdings shown'+(hiddenDust?' · '+hiddenDust+' small holdings hidden ('+money(dustValue)+')':'')+'. Totals include all known holdings; the dust filter retains unpriced tokens.'}
function renderInsights(){if($('portfolioInsights')&&window.OrbitInsights)$('portfolioInsights').innerHTML=OrbitInsights.render(state,{allocation:dashboardPrefs.allocation});applyDashboardPreferences();}

function renderAdvanced(){const host=$('advancedWorkspace');if(!host||!window.OrbitAdvanced)return;host.innerHTML=OrbitAdvanced.render(state);OrbitAdvanced.bind(host,{toggleWatch:async asset_id=>{await api('watch-toggle',{asset_id});await load();toast('Watchlist updated')},checkpoint:async()=>{await api('checkpoint',{});await load();toast('Wallet value checkpoint saved. This is not investment return.')},error:error=>toast(error?.message||String(error))});}
function renderTargets(){const host=$('targetWorkspace');if(!host||!window.OrbitTargets)return;host.innerHTML=OrbitTargets.render(state);OrbitTargets.bind(host,{save:async raw=>{const result=await api('target-save',raw);window.OrbitTargets?.resetDraft?.();await load();toast(result.evaluation?.triggered?'Target saved. A fresh saved quote matched the condition.':'Target saved. Conditions are checked on price refresh.')},remove:async id=>{await api('target-remove',{id});await load();toast('Target removed. Recorded events are retained.')},error:error=>toast(error?.message||String(error))});}
function mountMarkets(){if(!window.OrbitMarkets)return;OrbitMarkets.mount($('marketWorkspace'),{listings:()=>api('market-listings',{}),detail:coin_id=>api('market-detail',{coin_id}),chart:(coin_id,days,kind='line',source='coingecko')=>api('market-chart',{coin_id,days,kind,source}),fundamentals:coin_id=>api('market-fundamentals',{coin_id}),news:coin_id=>api('market-news',{coin_id}),watchlist:()=>api('market-watchlist',{}),toggleWatch:coin_id=>api('market-watch-toggle',{coin_id}),alertApi:(path,data)=>api(path,data),trades:()=>state.trades||[],holdings:()=>state,saveSetup:(key,value)=>api('chart-setup-save',{key,value}),loadSetup:key=>api('chart-setup-load',{key}).then(r=>r.value),error:toast});}
function knownQuote(value){return value!==null&&value!==undefined&&value!==''&&Number.isFinite(Number(value))&&Number(value)>=0}

function tokenQuoteStale(t){return !!(t.stale||t.price_stale||!t.price_fetched_at||Date.now()/1000-Number(t.price_fetched_at)>900)}

function tokenPriceCells(t){const priced=knownQuote(t.price_usd),valued=knownQuote(t.value_usd),stale=tokenQuoteStale(t);const price=priced?new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:8}).format(Number(t.price_usd)):'Unpriced';const observed=t.price_fetched_at?new Date(Number(t.price_fetched_at)*1000).toLocaleString():'Time unavailable';return '<td class="price-cell"><b>'+(priced&&Number(t.price_usd)>0&&Number(t.price_usd)<1e-8?'&lt;$0.00000001':price)+'</b>'+(priced?'<div class="small muted">'+esc(t.price_source||'Provider quote')+' · Quote observed '+esc(observed)+'</div>':'')+(t.price_error?'<div class="small negative">'+esc(t.price_error)+'</div>':'')+'</td><td class="value-cell"><b>'+(valued?money(Number(t.value_usd)):'Unpriced')+'</b>'+(valued?'<div class="small '+(stale?'negative':'muted')+'">'+(stale?'Stale · last known value':'Quote estimate')+'</div>':'')+'</td>'}

function walletValuationSummary(wallets,nativeValue,nativePriced){const tokens=wallets.flatMap(w=>(w.token_snapshot?.tokens||[]).filter(t=>t.quantity!==null&&t.quantity!==undefined&&!/^0(?:\.0+)?$/.test(String(t.quantity)))),priced=tokens.filter(t=>knownQuote(t.value_usd)),total=priced.reduce((n,t)=>n+Number(t.value_usd),0),stale=priced.filter(tokenQuoteStale).length,hasKnown=nativePriced+priced.length>0;return 'Known wallet value: '+(hasKnown?money(nativeValue+total):'Unpriced')+' · Native '+(nativePriced?money(nativeValue):'Unpriced')+' ('+nativePriced+'/'+wallets.length+' wallets valued) · Tokens '+(priced.length?money(total):'Unpriced')+' ('+priced.length+'/'+tokens.length+' nonzero holdings valued). '+(stale?stale+' token values stale. ':'')+'Partial coverage; unpriced assets are excluded. Token values are quote estimates. Wallet holdings are separate from recorded trades and are never added to trade holdings or used to infer P&L.'}



function preferenceKey(){return 'orbit.dashboard.v1:'+state.email}
function loadDashboardPreferences(){if(preferenceUser===state.email)return;preferenceUser=state.email;dashboardPrefs={allocation:'chain',compact:false,health:true,ledger:true};tokenControls={search:'',chain:'',sort:'value',dust:false,quote:'all'};try{const saved=JSON.parse(localStorage.getItem(preferenceKey())||'null');if(saved){dashboardPrefs={allocation:saved.allocation==='token'?'token':'chain',compact:saved.compact===true,health:saved.health!==false,ledger:saved.ledger!==false};tokenControls.sort=['value','name','low'].includes(saved.sort)?saved.sort:'value';tokenControls.dust=saved.dust===true;tokenControls.quote=['all','priced','unpriced','stale'].includes(saved.quote)?saved.quote:'all'}}catch{}}
function saveDashboardPreferences(){try{localStorage.setItem(preferenceKey(),JSON.stringify({...dashboardPrefs,sort:tokenControls.sort,dust:tokenControls.dust,quote:tokenControls.quote}));$('preferencesStatus').textContent='View saved on this browser'}catch{$('preferencesStatus').textContent='View applies to this session; browser storage unavailable'}}
function applyDashboardPreferences(){$('allocationView').value=dashboardPrefs.allocation;$('compactView').checked=dashboardPrefs.compact;$('showHealth').checked=dashboardPrefs.health;$('showLedger').checked=dashboardPrefs.ledger;document.body.classList.toggle('compact-dashboard',dashboardPrefs.compact);$('ledgerDashboard')?.classList.toggle('hidden',!dashboardPrefs.ledger);document.querySelector('#portfolioInsights [aria-label="Wallet data health"]')?.classList.toggle('hidden',!dashboardPrefs.health);$('portfolioInsights').classList.toggle('single-insight',!dashboardPrefs.health)}
for(const id of ['allocationView','compactView','showHealth','showLedger'])$(id).onchange=()=>{dashboardPrefs={allocation:$('allocationView').value,compact:$('compactView').checked,health:$('showHealth').checked,ledger:$('showLedger').checked};saveDashboardPreferences();renderInsights()};
$('resetDashboard').onclick=()=>{dashboardPrefs={allocation:'chain',compact:false,health:true,ledger:true};tokenControls={search:'',chain:'',sort:'value',dust:false,quote:'all'};saveDashboardPreferences();render()};
let dashboardPrivate=false;
$('dashboardPrivacy').onclick=()=>{dashboardPrivate=!dashboardPrivate;document.body.classList.toggle('dashboard-private',dashboardPrivate);$('dashboardPrivacy').textContent=dashboardPrivate?'Show dashboard amounts':'Hide dashboard amounts';$('dashboardPrivacy').setAttribute('aria-pressed',String(dashboardPrivate))};
load();



function renderNetworkSupport(){if(!state.network_support)return;$('providers').innerHTML=state.network_support.map(n=>'<div class="connection"><h3>'+esc(n.chain)+'</h3><span class="pill">'+(n.history_configured?'History enabled':'History setup required')+'</span><p>'+esc(n.history_coverage)+'</p>'+(['BNB Chain','Base','Arbitrum','Polygon','Sonic','Arc','Monad','Robinhood Chain','Linea'].includes(n.chain)&&!n.history_configured?'<p class="small">Set ETHERSCAN_API_KEY on the local server, then restart. Balance tracking still works.</p>':'')+'</div>').join('')}

function mountIntelligence(){if(!window.OrbitIntelligence)return;OrbitIntelligence.mount($('intelligenceWorkspace'),{overview:()=>api('intelligence-overview',{}),narratives:slug=>api('intelligence-narrative',{slug}),rsi:()=>api('intelligence-rsi',{}),venues:coin_id=>api('intelligence-venues',{coin_id}),microstructure:coin_id=>api('intelligence-flow',{coin_id}),derivatives:coin_id=>api('intelligence-derivatives',{coin_id}),exposures:coin_id=>api('intelligence-exposures',{coin_id}),listings:()=>api('market-listings',{}),watchlist:()=>api('market-watchlist',{}),toggleWatch:coin_id=>api('market-watch-toggle',{coin_id}),openCoin:coin_id=>{document.querySelector('[data-page="markets"]').click();window.OrbitMarkets?.openCoin?.($('marketWorkspace'),coin_id)},error:toast});}

const evmNetworks=['Ethereum','Optimism','BNB Chain','Base','Arbitrum','Polygon','Avalanche','Sonic','Gnosis','Celo','Arc','Monad','Robinhood Chain','Linea'];
$('chainCheckboxes').innerHTML=evmNetworks.map(chain=>'<label><input type="checkbox" value="'+esc(chain)+'">'+esc(chain)+'</label>').join('');
function updateChainChoices(){const compatible=evmNetworks.includes($('walletForm').elements.chain.value);$('chainChoices').classList.toggle('hidden',!compatible);if(!compatible)document.querySelectorAll('#chainCheckboxes input').forEach(x=>x.checked=false)}
$('walletForm').elements.chain.onchange=updateChainChoices;
$('selectAllChains').onclick=()=>document.querySelectorAll('#chainCheckboxes input').forEach(x=>x.checked=true);
$('clearChains').onclick=()=>document.querySelectorAll('#chainCheckboxes input').forEach(x=>x.checked=false);
updateChainChoices();

function mountExperience(page){const section=page==='connections'?'exchanges':page,host=$(page==='connections'?'exchangeWorkspace':page+'Workspace');window.OrbitExperience?.mount(host,{section,api:(path,data)=>api(path,data||{}),error:toast,onProfile:name=>{$('email').textContent=name||state.email},onPasswordChanged:()=>location.reload()})}
window.OrbitExperience?.installShell();
